+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import com.vaadin.flow.component.grid.Grid;
+import org.junit.jupiter.api.Test;
+
+import java.util.List;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    private Grid<?> vetGrid() {
+        navigate(VetsView.class);
+        return find(Grid.class).single();
+    }
+
+    private String cell(Grid<?> grid, int row, int column) {
+        return test(grid).getCellText(row, column);
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void gridShowsAllSeededVets() {
+        // Navigating without any authentication covers BR-003 (Anonymous Access).
+        Grid<?> grid = vetGrid();
+        assertEquals(6, test(grid).size());
+        assertEquals(List.of("First Name", "Last Name", "Specialties"),
+                grid.getColumns().stream().map(Grid.Column::getHeaderText).toList());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridLoadsLazily() {
+        Grid<?> grid = vetGrid();
+        assertTrue(grid.getDataProvider().isInMemory() == false,
+                "Expected a callback data provider, not an in-memory list");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreCommaSeparatedAlphabeticallyOrNone() {
+        Grid<?> grid = vetGrid();
+        // Ordered by last name: Carter, Douglas, Jenkins, Leary, Ortega, Stevens
+        assertEquals("none", cell(grid, 0, 2));
+        assertEquals("dentistry, surgery", cell(grid, 1, 2));
+    }
+}
